@androidx.media3.common.util.UnstableApi
public class LearningActivity extends Activity {
    private static final int INK=0xff173454,BLUE=0xff2159d6,MUTED=0xff566c84,BG=0xfff3f7fc,PALE=0xffe1ebfe;
    private static final String[] RATINGS={"미선별","못 떠올림","머뭇거림","나옴"},MODES={"듣고 익히기","받아쓰기","꺼내기·영작"};
    private Catalog catalog;private StudyStore store;private LinearLayout root;private String screen="home",kind="sort";
    private TextView clipLabel,clipPhonetic;private Button clipButton;
    private JSONObject task;private boolean preview=false;private MediaController controller;private ListenableFuture<MediaController> connection;
    private int mode=0,target=0,size=10,criterion=0;private List<Integer> explicitIds;private long entered;
    private String session=UUID.randomUUID().toString();private final Handler handler=new Handler(Looper.getMainLooper());
    @Override public void onCreate(Bundle state){super.onCreate(state);catalog=new Catalog(this);store=new StudyStore(this);criterion=store.criterion();if(state!=null){screen=state.getString("screen","home");kind=state.getString("kind","sort");}if(state!=null&&screen.equals("task")){task=store.task(kind);if(task.optJSONArray("ids")!=null)showTask();else showHome();}else showHome();}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("screen",screen);b.putString("kind",kind);}
    @Override protected void onStart(){super.onStart();var f=new MediaController.Builder(this,new SessionToken(this,new ComponentName(this,PlaybackService.class))).buildAsync();connection=f;f.addListener(()->{if(connection!=f)return;try{controller=f.get();if(screen.equals("home"))controller.sendCustomCommand(PlaybackService.RESTORE,Bundle.EMPTY);}catch(Exception ignored){}},ContextCompat.getMainExecutor(this));}
    @Override protected void onResume(){super.onResume();if(screen.equals("home"))showHome();}
    @Override protected void onStop(){if(connection!=null){MediaController.releaseFuture(connection);connection=null;controller=null;}super.onStop();}
    @Override protected void onDestroy(){store.close();super.onDestroy();}
    @Override public void onBackPressed(){if(screen.equals("home")){super.onBackPressed();}else showHome();}
    private int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
    private GradientDrawable bg(int color,int radius){var d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private TextView text(String s,int sp,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));return t;}
    private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private void gap(int h){View v=new View(this);root.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
    private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(INK);b.setMinHeight(dp(50));b.setBackground(bg(Color.WHITE,12));b.setPadding(dp(10),dp(7),dp(10),dp(7));b.setOnClickListener(v->action.run());return b;}
    private void addButton(String s,Runnable a){Button b=button(s,a);var p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));root.addView(b,p);}
    private void primary(String s,Runnable a){Button b=button(s,a);b.setBackground(bg(BLUE,12));b.setTextColor(Color.WHITE);var p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(10),0,dp(5));root.addView(b,p);}
    private void page(String title,String name){screen=name;ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);root=col();root.setPadding(dp(20),dp(12),dp(20),dp(25));scroll.addView(root);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});if(!name.equals("home")){var h=row();h.addView(button("‹ 홈",this::showHome),new LinearLayout.LayoutParams(dp(70),-2));TextView t=text(title,22,INK);t.setTypeface(null,Typeface.BOLD);t.setGravity(Gravity.CENTER);h.addView(t,new LinearLayout.LayoutParams(0,-2,1));h.addView(new View(this),new LinearLayout.LayoutParams(dp(70),1));root.addView(h);gap(16);}}
    private List<Catalog.Sentence> scope(){return catalog.select(catalog.filters(),0);}
    private String scopeName(){return catalog.filters().isEmpty()?"전체 문장":String.join(" + ",new TreeSet<>(catalog.filters()));}
    private String scopeLabel(){return scopeName()+" · "+scope().size()+"문장";}
    private void progress(int n,int total){ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);p.setProgressTintList(android.content.res.ColorStateList.valueOf(BLUE));p.setMax(Math.max(total,1));p.setProgress(n);root.addView(p,new LinearLayout.LayoutParams(-1,dp(6)));}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    private void openListen(boolean settings){stopPreview();Intent i=new Intent(this,MainActivity.class);i.putExtra("settings",settings);startActivity(i);}
    private String batchStatus(){JSONObject b=store.task("batch");JSONArray ids=b.optJSONArray("ids");if(ids==null||b.optInt("index")>=ids.length())return "새 묶음 만들기";return MODES[b.optInt("mode")]+" · "+b.optInt("index")+"/"+ids.length()+"\n"+(b.optString("scope").equals(scopeName())?"이어 하기":"이전 선정 · "+b.optString("scope"));}
    private void showHome(){hideKeyboard();stopPreview();if(controller!=null)controller.sendCustomCommand(PlaybackService.RESTORE,Bundle.EMPTY);explicitIds=null;page("","home");TextView title=text("뒹굴신 입영작\n1000문장",26,INK);title.setTypeface(null,Typeface.BOLD);root.addView(title);gap(18);var list=scope();int heard=0;Set<Integer> hs=store.heardIds();for(var s:list)if(hs.contains(s.id))heard++;int[] c=store.counts(list,criterion);JSONObject batch=store.task("batch");
        homeRow(new String[]{"카테고리 선정","듣고 익히기"},new String[]{catalog.prefs.getBoolean("scopeChosen",!catalog.filters().isEmpty())?scopeLabel()+"\n✓ 선정됨":"공부할 문장을 골라주세요",heard==0?"시작 전\n첫 문장부터 들어보기":"들어본 문장 "+heard+"/"+list.size()+"\n이어서 듣기"},new int[]{0,1},new Runnable[]{this::categories,()->openListen(false)},new int[]{-1,list.isEmpty()?0:heard*100/list.size()});
        homeRow(new String[]{"선별","묶음 학습"},new String[]{(criterion==0?"듣기 기준":"말하기 기준")+"\n나옴  "+c[3]+"\n머뭇거림  "+c[2]+"\n못 떠올림  "+c[1]+"\n미선별  "+c[0],batchStatus()},new int[]{2,3},new Runnable[]{()->entry("sort"),()->entry("batch")},new int[]{-1,batch.optJSONArray("ids")==null?-1:Math.min(100,batch.optInt("index")*100/Math.max(1,batch.optJSONArray("ids").length()))});
        homeRow(new String[]{"진도 체크","설정"},new String[]{"최근 7일\n나옴으로 변화 +"+store.gains(list,criterion)+"문장",(catalog.prefs.getBoolean("first",false)?"첫 발화만":"네 발화 모두")+" · "+catalog.prefs.getFloat("speed",1f)+"×\n재생 및 학습 설정"},new int[]{4,5},new Runnable[]{this::dashboard,()->openListen(true)},new int[]{-1,-1});
    }
    private void homeRow(String[] names,String[] notes,int[] icons,Runnable[] actions,int[] values){LinearLayout r=row();for(int i=0;i<2;i++){final Runnable action=actions[i];LinearLayout card=col();card.setPadding(dp(15),dp(14),dp(15),dp(14));card.setBackground(bg(Color.WHITE,15));card.setElevation(dp(2));card.setMinimumHeight(dp(175));card.setFocusable(true);card.setClickable(true);card.setContentDescription(names[i]+" "+notes[i]);card.setOnClickListener(v->action.run());card.addView(new Icon(this,icons[i]),new LinearLayout.LayoutParams(dp(27),dp(27)));TextView t=text(names[i],18,INK);t.setTypeface(null,Typeface.BOLD);card.addView(t);card.addView(text(notes[i],12,MUTED));if(values[i]>=0){ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);p.setProgress(values[i]);p.setProgressTintList(android.content.res.ColorStateList.valueOf(BLUE));card.addView(p,new LinearLayout.LayoutParams(-1,dp(5)));}var lp=new LinearLayout.LayoutParams(0,-1,1);lp.setMargins(i==0?0:dp(7),0,i==0?dp(7):0,0);r.addView(card,lp);}var lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(14));root.addView(r,lp);}
    private void categories(){var counts=catalog.categories();String[] keys=counts.keySet().toArray(new String[0]),labels=new String[keys.length];boolean[] checked=new boolean[keys.length];Set<String> chosen=catalog.filters();for(int n=0;n<keys.length;n++){labels[n]=keys[n]+" ("+counts.get(keys[n])+")";checked[n]=chosen.contains(keys[n]);}AlertDialog d=new AlertDialog.Builder(this).setTitle("카테고리 선정 · 모두 만족").setMultiChoiceItems(labels,checked,(a,n,b)->{if(b)chosen.add(keys[n]);else chosen.remove(keys[n]);((AlertDialog)a).setTitle("선정 대상 "+catalog.select(chosen,0).size()+"문장");}).setPositiveButton("선정 적용",null).setNeutralButton("전체 문장",null).setNegativeButton("취소",null).create();d.setOnShowListener(x->{d.getButton(-1).setOnClickListener(v->{if(catalog.select(chosen,0).isEmpty()){toast("조건을 줄여주세요. 모든 조건을 만족하는 문장이 없어요.");return;}applyScope(chosen);d.dismiss();});d.getButton(-3).setOnClickListener(v->{applyScope(Collections.emptySet());d.dismiss();});});d.show();}
    private void applyScope(Set<String> chosen){catalog.prefs.edit().putStringSet("filters",chosen).putBoolean("scopeChosen",true).putInt("studyFilter",0).putBoolean("scopeDirty",true).apply();if(controller!=null)controller.pause();showHome();}
    private void entry(String k){kind=k;target=k.equals("sort")?2:0;JSONObject saved=store.task(k);JSONArray ids=saved.optJSONArray("ids");if(ids!=null&&saved.optInt("index")<ids.length()){new AlertDialog.Builder(this).setTitle("진행 중인 "+(k.equals("sort")?"선별":"묶음 학습")).setMessage(saved.optString("scope")+"\n"+saved.optInt("index")+" / "+ids.length()+" 완료").setPositiveButton("이어 하기",(d,n)->{task=saved;showTask();}).setNeutralButton("새로 준비",(d,n)->prepare()).setNegativeButton("취소",null).show();}else prepare();}
    private void options(String label,String[] names,int selected,java.util.function.IntConsumer change){root.addView(text(label,14,MUTED));RadioGroup g=new RadioGroup(this);for(int i=0;i<names.length;i++){RadioButton b=new RadioButton(this);b.setText(names[i]);b.setTextColor(INK);b.setTextSize(14);b.setId(100+i);g.addView(b);if(i==selected)b.setChecked(true);}g.setOnCheckedChangeListener((a,id)->change.accept(id-100));root.addView(g);}
    private void prepare(){stopPreview();page(kind.equals("sort")?"선별 준비":"묶음 준비","prepare");root.addView(text(explicitIds==null?scopeLabel():"방금 학습한 "+explicitIds.size()+"문장",15,MUTED));if(kind.equals("sort")){options("선별 기준",new String[]{"듣기 기준","말하기·영작 기준"},criterion,n->{criterion=n;store.criterion(n);});}else options("학습 모드",MODES,mode,n->{mode=n;});
        if(explicitIds==null){if(!kind.equals("sort"))options("선별 기준으로 대상 고르기",new String[]{"듣기 상태","말하기·영작 상태"},criterion,n->{criterion=n;store.criterion(n);});options("학습 대상",new String[]{"어려운 문장 · 머뭇거림 + 못 떠올림","미선별 문장","선정한 전체 문장"},target,n->target=n);}if(kind.equals("batch"))options("이번 묶음 크기",new String[]{"5문장","10문장","20문장"},size==5?0:size==10?1:2,n->size=new int[]{5,10,20}[n]);
        primary(kind.equals("sort")?"선별 시작":"묶음 시작",this::startTask);if(kind.equals("batch"))addButton("먼저 선별하기",()->{kind="sort";prepare();});root.addView(text("진행 중인 문장 목록은 고정됩니다. 변경한 선정 조건은 새 묶음부터 적용돼요.",12,MUTED));}
    private void startTask(){List<Integer> ids=explicitIds==null?store.candidates(scope(),criterion,target):new ArrayList<>(explicitIds);if(ids.isEmpty()){toast("대상 문장이 없어요. 미선별 또는 전체를 선택해 주세요.");return;}if(kind.equals("batch")&&ids.size()>size)ids=new ArrayList<>(ids.subList(0,size));task=new JSONObject();StudyStore.put(task,"ids",new JSONArray(ids));StudyStore.put(task,"index",0);StudyStore.put(task,"criterion",criterion);StudyStore.put(task,"mode",mode);StudyStore.put(task,"scope",scopeName());StudyStore.put(task,"session",UUID.randomUUID().toString());StudyStore.put(task,"started",System.currentTimeMillis());StudyStore.put(task,"results",new JSONObject());save();store.event(task.optString("session"),"start",0,criterion,0,0,ids.size(),kind.equals("sort")?"selection":MODES[mode],0,scopeName(),task.optString("session"));showTask();}
    private void save(){store.task(kind,task);}
    private int taskId(){return task.optJSONArray("ids").optInt(task.optInt("index"));}
    private String eventKey(){return task.optString("session")+":"+task.optInt("index");}
    private JSONObject result(){JSONObject all=task.optJSONObject("results");if(all==null){all=new JSONObject();StudyStore.put(task,"results",all);}String k=""+task.optInt("index");JSONObject r=all.optJSONObject(k);if(r==null){r=new JSONObject();StudyStore.put(all,k,r);StudyStore.put(r,"entered",System.currentTimeMillis());}return r;}
    private void pauseListen(){if(controller!=null)controller.pause();}
    private void stopPreview(){if(preview&&controller!=null)controller.pause();preview=false;}
    private void audio(int id,int variant){if(controller==null){toast("재생기를 연결 중입니다. 잠시 뒤 다시 눌러주세요.");return;}Bundle args=new Bundle();args.putInt("id",id);args.putInt("variant",variant);args.putBoolean("masked",task!=null&&!result().optBoolean("revealed")&&!(kind.equals("batch")&&task.optInt("mode")==0));controller.sendCustomCommand(PlaybackService.AUDITION,args);preview=true;if(task!=null){StudyStore.put(result(),"lastVariant",variant);save();updateClip(catalog.sentence(id));}store.event(UUID.randomUUID().toString(),"preview",id,task==null?criterion:task.optInt("criterion"),0,0,0,kind,0,scopeName(),task==null?session:task.optString("session"));}
    private void showTask(){clipLabel=null;clipPhonetic=null;clipButton=null;pauseListen();int at=task.optInt("index"),total=task.optJSONArray("ids").length();if(at>=total){summary();return;}JSONObject r=result();save();boolean sort=kind.equals("sort"),revealed=r.optBoolean("revealed");int m=task.optInt("mode"),crit=task.optInt("criterion");Catalog.Sentence s=catalog.sentence(taskId());page(sort?"선별":MODES[m],"task");root.addView(text(task.optString("scope")+" · "+(at+1)+" / "+total,14,MUTED));progress(at,total);root.addView(text(sort?(crit==0?"듣기 기준":"말하기·영작 기준"):"이번 묶음",13,BLUE));gap(10);
        if(revealed||!sort&&m==0){answer(s);if(sort){root.addView(text("원문을 보기 전의 상태",15,INK));ratingButtons(r,s.id,crit);root.addView(text("판단이 달랐다면 수정할 수 있어요.",12,MUTED));}else if(m>0){String input=r.optString("input");if(!input.isEmpty()){root.addView(text("내 답: "+input,17,INK));boolean equal=StudyStore.normalize(input).equals(StudyStore.normalize(s.english));root.addView(text(equal?"원문과 일치합니다. 대소문자·구두점은 제외했어요.":m==1?"원문과 다른 부분을 비교해 보세요. 축약형·철자도 확인해 주세요.":"원문과 표현이 달라요. 다른 자연스러운 답도 가능하며, 자유 영작의 정오답 판정은 하지 않습니다.",13,MUTED));}else root.addView(text("내가 말한 내용과 원문을 비교해 보세요. 음성은 자동 채점하지 않습니다.",13,MUTED));}
            primary(at+1==total?"이번 학습 마치기":"다음 문장",()->advance(false));
        }else if(sort){if(crit==0){listeningCard(s);}else root.addView(text(s.korean,23,INK));gap(25);root.addView(text(crit==0?"뜻이 얼마나 수월하게 연결되나요?":"영어가 얼마나 수월하게 떠오르나요?",15,INK));ratingButtons(r,s.id,crit);addButton("건너뛰기",()->advance(true));
        }else{if(m==1){primary("▶ 듣기",()->audio(s.id,0));addButton("다시 듣기",()->audio(s.id,0));}else{root.addView(text(s.korean,23,INK));root.addView(text("영어로 먼저 말해보세요. 입력은 선택입니다.",14,MUTED));}EditText input=new EditText(this);input.setTextSize(18);input.setTextColor(INK);input.setHint(m==1?"들리는 영어를 입력하세요":"영어로 입력해서 확인");input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);input.setMinLines(2);input.setText(r.optString("input"));input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){StudyStore.put(r,"input",s.toString());save();}public void afterTextChanged(Editable e){}});root.addView(input);
            int hint=r.optInt("hint");if(hint>0){String[] words=s.english.split(" ");String clue=m==1&&hint==1?s.korean:hint==1?words[0]:String.join(" ",Arrays.copyOf(words,Math.max(1,words.length/2)))+" …";root.addView(text("힌트: "+clue,16,BLUE));}
            addButton(hint>=2?"전체 원문 보기":"힌트",()->{if(hint>=2){reveal(r,s,true);}else{StudyStore.put(r,"hint",hint+1);save();showTask();}});primary(m==2?"말했어요 · 답 확인":"답 확인",()->reveal(r,s,false));addButton("모르겠어요",()->reveal(r,s,true));}
        if(at>0)addButton("이전 문장",()->{stopPreview();StudyStore.put(task,"index",at-1);save();showTask();});addButton("여기까지 마치기",()->{if(kind.equals("sort")&&result().optBoolean("revealed")){StudyStore.put(result(),"done",true);StudyStore.put(task,"index",task.optInt("index")+1);save();}summary();});
    }
    private void listeningCard(Catalog.Sentence s){LinearLayout card=col();card.setGravity(Gravity.CENTER_HORIZONTAL);card.setPadding(dp(18),dp(22),dp(18),dp(20));card.setBackground(bg(Color.WHITE,20));TextView counter=text("이번 선별 · "+(task.optInt("index")+1)+"번째 문장",12,MUTED);card.addView(counter);addCyclePlayer(card,s);TextView prompt=text("듣고 뜻을 떠올려보세요",19,INK);prompt.setTypeface(null,Typeface.BOLD);prompt.setGravity(Gravity.CENTER);card.addView(prompt);TextView help=text("원문은 판단한 뒤에 보여드려요.",12,MUTED);help.setGravity(Gravity.CENTER);card.addView(help);root.addView(card);}
    private void addCyclePlayer(LinearLayout card,Catalog.Sentence s){
        LinearLayout player=col();player.setGravity(Gravity.CENTER_HORIZONTAL);
        clipButton=button("▶",()->audio(s.id,(result().optInt("lastVariant",-1)+1)%4));
        clipButton.setTextSize(28);clipButton.setTextColor(Color.WHITE);clipButton.setBackground(bg(BLUE,44));
        var lp=new LinearLayout.LayoutParams(dp(88),dp(88));lp.setMargins(0,dp(16),0,dp(6));player.addView(clipButton,lp);
        clipLabel=text("",12,MUTED);clipLabel.setGravity(Gravity.CENTER);player.addView(clipLabel);
        card.addView(player,new LinearLayout.LayoutParams(-1,-2));updateClip(s);
    }
    private void updateClip(Catalog.Sentence s){
        int last=result().optInt("lastVariant",-1),next=(last+1)%4;
        if(clipLabel!=null)clipLabel.setText((last<0?"": "발화 "+(last+1)+" / 4 · ")+"누르면 발화 "+(next+1));
        if(clipButton!=null)clipButton.setContentDescription("발화 "+(next+1)+" 재생");
        if(clipPhonetic!=null)clipPhonetic.setText(s.sounds[Math.max(0,last)]);
    }
    private void ratingButtons(JSONObject r,int id,int crit){LinearLayout row=row();for(int n=1;n<=3;n++){final int value=n;Button b=button((r.optInt("rating")==n?"✓ ":"")+RATINGS[n],()->{store.rate(eventKey(),id,crit,value,task.optString("scope"),task.optString("session"));StudyStore.put(r,"rating",value);StudyStore.put(r,"revealed",true);save();showTask();});if(r.optInt("rating")==n){b.setBackground(bg(PALE,12));b.setTextColor(BLUE);}var lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),dp(5),dp(3),dp(5));row.addView(b,lp);}root.addView(row);}
    private void answer(Catalog.Sentence s){LinearLayout card=col();card.setPadding(dp(18),dp(14),dp(18),dp(14));card.setBackground(bg(Color.WHITE,20));card.addView(text(s.id+"번 · 원문 확인",12,MUTED));TextView en=text(s.english,23,INK);en.setTypeface(null,Typeface.BOLD);card.addView(en);card.addView(text(s.korean,16,MUTED));TextView ph=text(s.sounds[Math.max(0,result().optInt("lastVariant",-1))],30,BLUE);clipPhonetic=ph;ph.setTypeface(null,Typeface.BOLD);card.addView(ph);addCyclePlayer(card,s);card.addView(button("발음별 듣기·해설 보기",()->{LinearLayout info=col();for(int v=0;v<4;v++){final int variant=v;info.addView(button("발화 "+(v+1)+" · "+s.sounds[v],()->audio(s.id,variant)));}info.addView(text(s.explanation,14,MUTED));ScrollView scroll=new ScrollView(this);scroll.addView(info);new AlertDialog.Builder(this).setTitle(s.id+"번 해설").setView(scroll).setPositiveButton("닫기",null).show();}));root.addView(card);}
    private void reveal(JSONObject r,Catalog.Sentence s,boolean giveup){if(r.optBoolean("revealed"))return;StudyStore.put(r,"revealed",true);if(giveup)StudyStore.put(r,"hint",3);StudyStore.put(r,"elapsed",Math.max(0,System.currentTimeMillis()-r.optLong("entered")));save();recordAnswer(r,s);hideKeyboard();showTask();}
    private void recordAnswer(JSONObject r,Catalog.Sentence s){boolean equal=!r.optString("input").isEmpty()&&StudyStore.normalize(r.optString("input")).equals(StudyStore.normalize(s.english));store.event(eventKey(),"answer",s.id,task.optInt("criterion"),0,equal?1:0,r.optLong("elapsed"),MODES[task.optInt("mode")],r.optInt("hint"),task.optString("scope"),task.optString("session"));}
    private void hideKeyboard(){View v=getCurrentFocus();if(v!=null)((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(v.getWindowToken(),0);}
    private void advance(boolean skip){stopPreview();JSONObject r=result();if(kind.equals("batch")&&task.optInt("mode")==0&&!r.optBoolean("done"))recordAnswer(r,catalog.sentence(taskId()));StudyStore.put(r,"done",true);StudyStore.put(r,"skipped",skip);StudyStore.put(task,"index",task.optInt("index")+1);save();showTask();}
    private void summary(){stopPreview();hideKeyboard();page(kind.equals("sort")?"선별 결과":"묶음 학습 기록","summary");JSONArray ids=task.optJSONArray("ids");int[] counts=new int[4];int completed=0,hints=0;JSONObject results=task.optJSONObject("results");List<Integer> difficult=new ArrayList<>(),touched=new ArrayList<>();for(int i=0;i<ids.length();i++){JSONObject r=results.optJSONObject(""+i);if(r==null)continue;if(r.optBoolean("done"))completed++;if(r.optBoolean("revealed")||r.optBoolean("done"))touched.add(ids.optInt(i));counts[r.optInt("rating")]++;if(r.optInt("rating")==1||r.optInt("rating")==2)difficult.add(ids.optInt(i));if(r.optInt("hint")>0)hints++;}root.addView(text(task.optString("scope"),14,MUTED));root.addView(text(completed+" / "+ids.length()+"문장 확인",25,INK));progress(completed,ids.length());root.addView(text(kind.equals("sort")?"나옴 "+counts[3]+" · 머뭇거림 "+counts[2]+" · 못 떠올림 "+counts[1]:"힌트 사용 "+hints+"문장\n학습 완료와 체득 여부는 다릅니다. 선별 상태는 자동으로 바뀌지 않아요.",15,MUTED));
        if(completed<ids.length())primary("이어 하기",this::showTask);
        if(kind.equals("sort")){if(!difficult.isEmpty())addButton("어려운 "+difficult.size()+"문장으로 묶음 학습",()->{explicitIds=difficult;kind="batch";prepare();});}else{if(!touched.isEmpty())addButton("이번 문장 다시 선별하기",()->{explicitIds=touched;kind="sort";prepare();});addButton("같은 문장으로 다른 모드",()->{explicitIds=new ArrayList<>();for(int i=0;i<ids.length();i++)explicitIds.add(ids.optInt(i));kind="batch";prepare();});addButton("다음 묶음 준비",()->{explicitIds=null;kind="batch";prepare();});}addButton("홈으로",this::showHome);}
    private void dashboard(){page("진도 체크","dashboard");root.addView(text(scopeLabel(),15,MUTED));options("선별 기준",new String[]{"듣기 기준","말하기·영작 기준"},criterion,n->{criterion=n;store.criterion(n);dashboard();});int[] c=store.counts(scope(),criterion);root.addView(text("현재 나옴 "+c[3]+" / "+scope().size()+"문장",24,INK));progress(c[3],scope().size());for(int n=0;n<4;n++){final int value=n;addButton(RATINGS[n]+" · "+c[n]+"문장",()->stateList(value));}root.addView(text("최근 7일, 어려웠다가 나옴으로 변화\n"+store.gains(scope(),criterion)+"문장",19,BLUE));gap(12);root.addView(text(store.analysis(scope(),criterion),14,MUTED));int[] all=store.counts(catalog.sentences,criterion);root.addView(text("전체 1,000문장 · 나옴 "+all[3]+" · 미선별 "+all[0]+"\n카테고리가 겹쳐도 같은 문장은 한 번만 셉니다.",13,MUTED));}
    private void stateList(int value){List<Integer> ids=new ArrayList<>();StringBuilder s=new StringBuilder();for(var x:scope())if(store.rating(x.id,criterion)==value){ids.add(x.id);s.append(x.id+". "+x.english+"\n");}if(ids.isEmpty()){toast("해당 문장이 없습니다.");return;}new AlertDialog.Builder(this).setTitle(RATINGS[value]+" · "+ids.size()+"문장").setMessage(s.toString()).setPositiveButton("다시 선별",(d,n)->{explicitIds=ids;kind="sort";prepare();}).setNeutralButton("묶음 학습",(d,n)->{explicitIds=ids;kind="batch";prepare();}).setNegativeButton("닫기",null).show();}
    private static final class Icon extends View {final int which;final Paint paint=new Paint(3);Icon(Context c,int w){super(c);which=w;}@Override protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.save();canvas.scale(getWidth()/24f,getHeight()/24f);paint.setColor(BLUE);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1.7f);paint.setStrokeCap(Paint.Cap.ROUND);switch(which){case 0:for(int y=3;y<20;y+=11)for(int x=3;x<20;x+=11)canvas.drawRoundRect(x,y,x+7,y+7,2,2,paint);break;case 1:canvas.drawArc(4,3,20,20,180,180,false,paint);canvas.drawRoundRect(3,11,7,21,2,2,paint);canvas.drawRoundRect(17,11,21,21,2,2,paint);break;case 2:canvas.drawLine(12,2,12,10,paint);canvas.drawLine(5,10,19,10,paint);for(int x=5;x<=19;x+=7){canvas.drawLine(x,10,x,15,paint);canvas.drawCircle(x,19,2,paint);}break;case 3:canvas.drawRoundRect(7,2,22,18,2,2,paint);canvas.drawRoundRect(2,7,17,23,2,2,paint);break;case 4:canvas.drawLine(3,2,3,21,paint);canvas.drawLine(3,21,22,21,paint);Path p=new Path();p.moveTo(7,16);p.lineTo(12,10);p.lineTo(16,12);p.lineTo(22,4);canvas.drawPath(p,paint);break;default:canvas.drawCircle(12,12,7,paint);canvas.drawCircle(12,12,3,paint);for(int a=0;a<360;a+=45){double r=Math.toRadians(a);canvas.drawLine(12+(float)Math.cos(r)*7,12+(float)Math.sin(r)*7,12+(float)Math.cos(r)*10,12+(float)Math.sin(r)*10,paint);}}canvas.restore();}}
}
